import React from 'react'

export default function Community() {
    return (
        <div>
            <h1 className="text-2xl font-bold text-gray-800">👥 Community</h1>
            <p className="text-gray-500 mt-2">Share predictions and discuss matches</p>
            <div className="mt-6 bg-white rounded-xl shadow-md p-6 text-center text-gray-400">
                Coming soon: Post, comment, and share predictions!
            </div>
        </div>
    )
}
